/* 与预览的 Number(value.toFixed(3)).toString() 保持相同小数刻度格式。 */
static void chart_format_value(char * text, size_t capacity, double value) {
    /* 精确的二进制半值（奇数/16）按 JS toFixed 的远离零规则舍入。 */
    double sixteenths = value * 16;
    int64_t numerator = (int64_t)sixteenths;
    if((double)numerator == sixteenths && numerator % 2 != 0) value += value < 0 ? -0.0005 : 0.0005;
    snprintf(text, capacity, "%.3f", value);
    char * decimal = strchr(text, '.');
    if(decimal) {
        char * end = text + strlen(text) - 1;
        while(end > decimal && *end == '0') *end-- = 0;
        if(end == decimal) *end = 0;
    }
    if(strcmp(text, "-0") == 0) strcpy(text, "0");
}
