static void chart_event(lv_event_t * event) {
    ui_chart_context_t * c = lv_event_get_user_data(event);
    lv_event_code_t code = lv_event_get_code(event);
    /* 留白和视口同属一个业务控件，输入事件统一以公开 Chart 作为目标。 */
    if(lv_event_get_target(event) != c->chart && !c->forwarding &&
       (code == LV_EVENT_PRESSED || code == LV_EVENT_PRESSING || code == LV_EVENT_PRESS_LOST ||
        code == LV_EVENT_SHORT_CLICKED || code == LV_EVENT_LONG_PRESSED || code == LV_EVENT_LONG_PRESSED_REPEAT ||
        code == LV_EVENT_CLICKED || code == LV_EVENT_RELEASED || code == LV_EVENT_KEY || code == LV_EVENT_FOCUSED || code == LV_EVENT_DEFOCUSED)) {
        lv_obj_t * chart = c->chart;
        c->forwarding = true;
        lv_obj_send_event(chart, code, lv_event_get_param(event));
        if(chart_context(chart) == c) c->forwarding = false;
        return;
    }
    if(code == LV_EVENT_DELETE && lv_event_get_target(event) == c->root) c->root_deleting = true;
    if(code == LV_EVENT_DELETE && lv_event_get_target(event) == c->chart) {
        ui_chart_context_t ** p = &chart_contexts;
        while(*p && *p != c) p = &(*p)->next;
        if(*p) *p = c->next;
        /* 外框或视口可晚于 Chart 销毁，先移除持有上下文指针的回调。 */
        if(lv_obj_is_valid(c->root)) lv_obj_remove_event_cb_with_user_data(c->root, chart_event, c);
        if(lv_obj_is_valid(c->viewport)) lv_obj_remove_event_cb_with_user_data(c->viewport, chart_event, c);
        chart_release_labels(c);
        /* 公开的 Chart 删除也回收私有外框；父树删除时不能再次排队删除父对象。 */
        if(!c->root_deleting && lv_obj_is_valid(c->root)) lv_obj_delete_async(c->root);
        lv_free(c);
        return;
    }
    if(code == LV_EVENT_SIZE_CHANGED || code == LV_EVENT_SCROLL || code == LV_EVENT_STYLE_CHANGED) _deepui_chart_sync(c->chart);
}
