void _deepui_chart_axis(lv_obj_t * chart, int axis, bool enabled, int major_length, int major_count, int minor_length, int minor_count, bool labels, const lv_font_t * font) {
    ui_chart_context_t * c = chart_context(chart);
    if(!c || axis < 0 || axis > 2) return;
    c->axis[axis] = (ui_chart_axis_t){ enabled, labels, major_length, major_count, minor_length, minor_count, font };
    _deepui_chart_sync(chart);
}
void _deepui_chart_axis_font(lv_obj_t * chart, int axis, const lv_font_t * font) {
    ui_chart_context_t * c = chart_context(chart);
    if(!c || axis < 0 || axis > 2 || c->axis[axis].font == font) return;
    /* 语言切换仅刷新刻度字体，不重建序列或改变缩放、滚动状态。 */
    c->axis[axis].font = font;
    _deepui_chart_sync(chart);
}
void _deepui_chart_view(lv_obj_t * chart, int zoom_x, int zoom_y, int32_t x_min, int32_t x_max, int32_t y_min, int32_t y_max, int32_t secondary_min, int32_t secondary_max) {
    ui_chart_context_t * c = chart_context(chart);
    if(!c) return;
    c->zoom_x = zoom_x; c->zoom_y = zoom_y;
    c->ranges[0][0] = x_min; c->ranges[0][1] = x_max;
    c->ranges[1][0] = y_min; c->ranges[1][1] = y_max;
    c->ranges[2][0] = secondary_min; c->ranges[2][1] = secondary_max;
    _deepui_chart_sync(chart);
}
