#if LV_USE_DROPDOWN
static void dropdown_open_deferred(void * target);
static void dropdown_cancel_deferred(lv_event_t * event)
{
    lv_async_call_cancel(dropdown_open_deferred, lv_event_get_target(event));
}
static void dropdown_open_deferred(void * target)
{
    lv_obj_t * object = target;
    lv_obj_remove_event_cb(object, dropdown_cancel_deferred);
    lv_obj_update_layout(lv_obj_get_screen(object));
    lv_dropdown_open(object);
}
void _deepui_dropdown_open_after_layout(lv_obj_t * target)
{
    /* 延后至整个屏幕及组件兄弟布局完成；提前删除控件时取消待执行回调。 */
    lv_obj_add_event_cb(target, dropdown_cancel_deferred, LV_EVENT_DELETE, NULL);
    lv_async_call(dropdown_open_deferred, target);
}
void _deepui_dropdown_set_options(lv_obj_t * target, const char * const * options, uint32_t count)
{
    if (target == NULL) return;
    size_t length = 1;
    for (uint32_t i = 0; i < count; i++) length += strlen(options[i]) + 1;
    char * text = lv_malloc(length);
    if (text == NULL) return;
    char * output = text;
    for (uint32_t i = 0; i < count; i++) {
        if (i) *output++ = '\n';
        for (const char * p = options[i]; *p; p++) *output++ = *p == '\n' || *p == '\r' ? ' ' : *p;
    }
    *output = 0;
    /* 语言刷新只替换选项文字，保留用户实时选择及列表展开状态。 */
    uint32_t selected = lv_dropdown_get_selected(target);
    bool opened = lv_dropdown_is_open(target);
    if (opened) lv_dropdown_close(target);
    lv_dropdown_set_options(target, text);
    lv_obj_t * list = lv_dropdown_get_list(target);
    lv_obj_t * label = list != NULL ? lv_obj_get_child(list, 0) : NULL;
    if (label != NULL) lv_label_set_text(label, lv_dropdown_get_options(target));
    lv_dropdown_set_selected(target, selected);
    if (opened) lv_dropdown_open(target);
    lv_free(text);
}
#endif

