void _deepui_roller_set_options(lv_obj_t * target, const char * const * options, uint32_t count, lv_roller_mode_t mode)
{
    if (target == NULL) return;
    size_t length = 1;
    for (uint32_t i = 0; i < count; i++) length += strlen(options[i]) + 1;
    char * text = lv_malloc(length);
    if (text == NULL) return;
    char * output = text;
    for (uint32_t i = 0; i < count; i++) {
        if (i) *output++ = '\n';
        /* 译文中的换行只作空格显示，不能改变选项个数及选中索引。 */
        for (const char * p = options[i]; *p; p++) *output++ = *p == '\n' || *p == '\r' ? ' ' : *p;
    }
    *output = 0;
    /* 更新语言时保留用户实时选择，不恢复工程中的初始索引。 */
    uint32_t selected = lv_roller_get_selected(target);
    lv_roller_set_options(target, text, mode);
    lv_roller_set_selected(target, selected, LV_ANIM_OFF);
    lv_free(text);
}
