#if LV_USE_TEXTAREA
static uint32_t textarea_next_character(const char ** cursor)
{
    const unsigned char * start = (const unsigned char *)*cursor;
    unsigned char lead = *start;
    unsigned count = lead < 0x80 ? 1 : (lead & 0xe0) == 0xc0 ? 2 : (lead & 0xf0) == 0xe0 ? 3 : (lead & 0xf8) == 0xf0 ? 4 : 1;
    uint32_t value = count == 1 ? lead : lead & ((1u << (7 - count)) - 1);
    for (unsigned i = 1; i < count; i++) {
        if ((start[i] & 0xc0) != 0x80) { *cursor += 1; return lead; }
        value = (value << 6) | (start[i] & 0x3f);
    }
    *cursor += count;
    return value;
}

void _deepui_textarea_set_text(lv_obj_t * target, const char * text)
{
    if (target == NULL || text == NULL) return;
    /* 按 Unicode 字符过滤后再计数，避免 UTF-8 截断及 8.x 密码缓存保存未过滤正文。 */
    char * filtered = lv_malloc(strlen(text) + 1);
    if (filtered == NULL) return;
    const char * allowed = lv_textarea_get_accepted_chars(target);
    const uint32_t maximum = lv_textarea_get_max_length(target);
    const bool one_line = lv_textarea_get_one_line(target);
    char * output = filtered;
    uint32_t length = 0;
    while (*text != '\0') {
        const char * start = text;
        uint32_t character = textarea_next_character(&text);
        if (one_line && (character == '\n' || character == '\r')) continue;
        if (allowed != NULL && *allowed != '\0') {
            const char * candidate = allowed;
            bool found = false;
            while (*candidate != '\0') {
                if (textarea_next_character(&candidate) == character) { found = true; break; }
            }
            if (!found) continue;
        }
        if (maximum > 0 && length >= maximum) break;
        size_t bytes = (size_t)(text - start);
        memcpy(output, start, bytes);
        output += bytes;
        length++;
    }
    *output = '\0';
    lv_textarea_set_text(target, filtered);
    lv_free(filtered);
}
#endif

void _deepui_object_deleted(lv_event_t * e)
{
    /* 引用随对象自身删除失效，不依赖屏幕析构入口。 */
    lv_obj_t ** reference = (lv_obj_t **)lv_event_get_user_data(e);
    if (reference != NULL && *reference == lv_event_get_target(e)) *reference = NULL;
}

/* 将事件动作中的属性编号转换为 LVGL 调用；空句柄直接跳过。
 * 数值修改辅助函数中，Arc、Slider 和 Spinbox 还会发送 VALUE_CHANGED 通知。 */
void _deepui_basic_set_property(lv_obj_t * target, int id, int val)
{
    if(target == NULL) return;
    target = _deepui_chart_get_layout_root(target);
    if(id == _DEEPUI_BASIC_PROPERTY_POSITION_X) lv_obj_set_x(target, val);
    else if(id == _DEEPUI_BASIC_PROPERTY_POSITION_Y) lv_obj_set_y(target, val);
    else if(id == _DEEPUI_BASIC_PROPERTY_WIDTH) lv_obj_set_width(target, val);
    else if(id == _DEEPUI_BASIC_PROPERTY_HEIGHT) lv_obj_set_height(target, val);
}

void _deepui_label_set_property(lv_obj_t * target, int id, const char * val)
{
    if(target == NULL || val == NULL) return;
    if(id == _DEEPUI_LABEL_PROPERTY_TEXT) lv_label_set_text(target, val);
}

void _deepui_arc_set_property(lv_obj_t * target, int id, int val)
{
    if(target == NULL) return;
    if(id == _DEEPUI_ARC_PROPERTY_VALUE) {
        lv_arc_set_value(target, val);
        lv_obj_send_event(target, LV_EVENT_VALUE_CHANGED, NULL);
    }
}

void _deepui_bar_set_property(lv_obj_t * target, int id, int val)
{
    if(target == NULL) return;
    if(id == _DEEPUI_BAR_PROPERTY_VALUE) lv_bar_set_value(target, val, LV_ANIM_OFF);
    else if(id == _DEEPUI_BAR_PROPERTY_VALUE_WITH_ANIM) lv_bar_set_value(target, val, LV_ANIM_ON);
}

void _deepui_slider_set_property(lv_obj_t * target, int id, int val)
{
    if(target == NULL) return;
    if(id == _DEEPUI_SLIDER_PROPERTY_VALUE || id == _DEEPUI_SLIDER_PROPERTY_VALUE_WITH_ANIM) {
        lv_slider_set_value(target, val, id == _DEEPUI_SLIDER_PROPERTY_VALUE_WITH_ANIM ? LV_ANIM_ON : LV_ANIM_OFF);
        lv_obj_send_event(target, LV_EVENT_VALUE_CHANGED, NULL);
    }
}

void _deepui_dropdown_set_property(lv_obj_t * target, int id, int val)
{
    if(target == NULL) return;
    if(id == _DEEPUI_DROPDOWN_PROPERTY_SELECTED) lv_dropdown_set_selected(target, val);
}

void _deepui_roller_set_property(lv_obj_t * target, int id, int val)
{
    if(target == NULL) return;
    if(id == _DEEPUI_ROLLER_PROPERTY_SELECTED || id == _DEEPUI_ROLLER_PROPERTY_SELECTED_WITH_ANIM) {
        lv_roller_set_selected(target, val, id == _DEEPUI_ROLLER_PROPERTY_SELECTED_WITH_ANIM ? LV_ANIM_ON : LV_ANIM_OFF);
    }
}

void _deepui_image_set_property(lv_obj_t * target, int id, const void * val)
{
    if(target == NULL || val == NULL) return;
    if(id == _DEEPUI_IMAGE_PROPERTY_IMAGE) lv_image_set_src(target, val);
}

static void _deepui_format_value(char * buf, size_t size, int32_t value, const char * prefix, const char * postfix)
{
    lv_snprintf(buf, size, "%s%d%s", prefix ? prefix : "", (int)value, postfix ? postfix : "");
}

/* 独立占位屏幕只用于安全删除活动屏幕，不属于工程屏幕，也不放入 deepui_ui。 */
static lv_obj_t * fallback_screen;
void _deepui_release_fallback_screen(void)
{
    if(fallback_screen != NULL && lv_screen_active() != fallback_screen) {
        lv_obj_delete(fallback_screen);
        fallback_screen = NULL;
    }
}
void _deepui_screen_destroy(lv_obj_t ** target)
{
    if(target == NULL || *target == NULL) return;
    /* 删除活动屏幕前切到独立占位屏幕，不把临时导航状态混入对象结构体。 */
    if(lv_screen_active() == *target) {
        if(fallback_screen == NULL) {
            fallback_screen = lv_obj_create(NULL);
            lv_obj_add_event_cb(fallback_screen, _deepui_object_deleted, LV_EVENT_DELETE, &fallback_screen);
        }
        lv_screen_load(fallback_screen);
    }
    lv_obj_delete(*target);
    *target = NULL;
}

void _deepui_screen_change(lv_obj_t ** target, int fademode, uint32_t speed, uint32_t delay)
{
    /* DEEPUI_CUSTOM_CODE_ID 5958bab0-0d8c-4632-aa47-cbe391ab2dfa */
    /* DEEPUI_EXIDE_CUSTOM_CODE_BEGIN implementation */
    /* DEEPUI_EXIDE_CUSTOM_CODE_END implementation */

    if(target == NULL || *target == NULL) return;
    /* 仅自动删除临时占位屏幕；工程中的旧屏幕保留，以便以后再次切回。 */
#if LVGL_VERSION_MAJOR >= 9
    lv_screen_load_anim(*target, (lv_screen_load_anim_t)fademode, speed, delay, lv_screen_active() == fallback_screen);
#else
    lv_scr_load_anim(*target, (lv_scr_load_anim_t)fademode, speed, delay, lv_scr_act() == fallback_screen);
#endif
    /* DEEPUI_CUSTOM_CODE_ID 0f359e93-625e-45ce-8031-f4f51b0ec053 */
    /* DEEPUI_EXIDE_CUSTOM_CODE_BEGIN implementation */
    /* DEEPUI_EXIDE_CUSTOM_CODE_END implementation */

}

void _deepui_flag_modify(lv_obj_t * target, lv_obj_flag_t flag, deepui_modify_flag_t action)
{
    if(target == NULL) return;
    lv_obj_t * layout = _deepui_chart_get_layout_root(target);
    if(layout != target) _deepui_flag_modify(layout, flag, action);
    if(action == _DEEPUI_MODIFY_FLAG_ADD) lv_obj_add_flag(target, flag);
    else if(action == _DEEPUI_MODIFY_FLAG_REMOVE) lv_obj_remove_flag(target, flag);
    else {
        if(lv_obj_has_flag(target, flag)) lv_obj_remove_flag(target, flag);
        else lv_obj_add_flag(target, flag);
    }
}

void _deepui_state_modify(lv_obj_t * target, lv_state_t state, deepui_modify_state_t action)
{
    if(target == NULL) return;
    lv_obj_t * layout = _deepui_chart_get_layout_root(target);
    if(layout != target) _deepui_state_modify(layout, state, action);
    if(action == _DEEPUI_MODIFY_STATE_ADD) lv_obj_add_state(target, state);
    else if(action == _DEEPUI_MODIFY_STATE_REMOVE) lv_obj_remove_state(target, state);
    else {
        if(lv_obj_has_state(target, state)) lv_obj_remove_state(target, state);
        else lv_obj_add_state(target, state);
    }
}

void _deepui_opacity_set(lv_obj_t * target, int32_t value)
{
    if(target != NULL) lv_obj_set_style_opa(_deepui_chart_get_layout_root(target), (lv_opa_t)value, LV_PART_MAIN | LV_STATE_DEFAULT);
}

void _deepui_arc_increment(lv_obj_t * target, int32_t value, int anim)
{
    if(target != NULL) lv_arc_set_value(target, lv_arc_get_value(target) + value);
    if(target != NULL) lv_obj_send_event(target, LV_EVENT_VALUE_CHANGED, NULL);
    (void)anim;
}

void _deepui_bar_increment(lv_obj_t * target, int32_t value, int anim)
{
    if(target != NULL) lv_bar_set_value(target, lv_bar_get_value(target) + value, anim ? LV_ANIM_ON : LV_ANIM_OFF);
}

void _deepui_slider_increment(lv_obj_t * target, int32_t value, int anim)
{
    if(target != NULL) lv_slider_set_value(target, lv_slider_get_value(target) + value, anim ? LV_ANIM_ON : LV_ANIM_OFF);
    if(target != NULL) lv_obj_send_event(target, LV_EVENT_VALUE_CHANGED, NULL);
}

void _deepui_keyboard_set_target(lv_obj_t * keyboard, lv_obj_t * textarea)
{
    if(keyboard != NULL) lv_keyboard_set_textarea(keyboard, textarea);
}

void _deepui_textarea_move_cursor(lv_obj_t * textarea, deepui_move_cursor_dir_t dir)
{
    if(textarea == NULL) return;
    if(dir == DEEPUI_UI_MOVE_CURSOR_LEFT) lv_textarea_cursor_left(textarea);
    else if(dir == DEEPUI_UI_MOVE_CURSOR_RIGHT) lv_textarea_cursor_right(textarea);
    else if(dir == DEEPUI_UI_MOVE_CURSOR_UP) lv_textarea_cursor_up(textarea);
    else if(dir == DEEPUI_UI_MOVE_CURSOR_DOWN) lv_textarea_cursor_down(textarea);
}

void _deepui_arc_set_text_value(lv_obj_t * label, lv_obj_t * arc, const char * prefix, const char * postfix)
{
    if(label == NULL || arc == NULL) return;
    char buf[64];
    _deepui_format_value(buf, sizeof(buf), lv_arc_get_value(arc), prefix, postfix);
    lv_label_set_text(label, buf);
}

void _deepui_slider_set_text_value(lv_obj_t * label, lv_obj_t * slider, const char * prefix, const char * postfix)
{
    if(label == NULL || slider == NULL) return;
    char buf[64];
    _deepui_format_value(buf, sizeof(buf), lv_slider_get_value(slider), prefix, postfix);
    lv_label_set_text(label, buf);
}

void _deepui_checked_set_text_value(lv_obj_t * label, lv_obj_t * source, const char * on_text, const char * off_text)
{
    if(label == NULL || source == NULL) return;
    lv_label_set_text(label, lv_obj_has_state(source, LV_STATE_CHECKED) ? on_text : off_text);
}

void _deepui_spinbox_step(lv_obj_t * spinbox, int dir)
{
    if(spinbox == NULL) return;
    if(dir < 0) lv_spinbox_decrement(spinbox);
    else lv_spinbox_increment(spinbox);
    lv_obj_send_event(spinbox, LV_EVENT_VALUE_CHANGED, NULL);
}

void _deepui_obj_set_property(lv_obj_t * obj, const char * property, const char * value)
{
    if(obj == NULL || property == NULL || value == NULL) return;
    if(strcmp(property, "text") == 0) {
        lv_label_set_text(obj, value);
    }
}

/* 动画引擎通过 user_data 找到当前属性的目标及图片帧列表。 */
static deepui_anim_user_data_t * _deepui_anim_user_data(lv_anim_t * a)
{
    return (deepui_anim_user_data_t *)lv_anim_get_user_data(a);
}

void _deepui_anim_callback_set_x(lv_anim_t * a, int32_t v) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); if(d && d->target) lv_obj_set_x(_deepui_chart_get_layout_root(d->target), v); }
int32_t _deepui_anim_callback_get_x(lv_anim_t * a) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); return d && d->target ? lv_obj_get_x_aligned(_deepui_chart_get_layout_root(d->target)) : 0; }
void _deepui_anim_callback_set_y(lv_anim_t * a, int32_t v) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); if(d && d->target) lv_obj_set_y(_deepui_chart_get_layout_root(d->target), v); }
int32_t _deepui_anim_callback_get_y(lv_anim_t * a) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); return d && d->target ? lv_obj_get_y_aligned(_deepui_chart_get_layout_root(d->target)) : 0; }
void _deepui_anim_callback_set_width(lv_anim_t * a, int32_t v) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); if(d && d->target) lv_obj_set_width(_deepui_chart_get_layout_root(d->target), v); }
int32_t _deepui_anim_callback_get_width(lv_anim_t * a) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); return d && d->target ? lv_obj_get_width(_deepui_chart_get_layout_root(d->target)) : 0; }
void _deepui_anim_callback_set_height(lv_anim_t * a, int32_t v) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); if(d && d->target) lv_obj_set_height(_deepui_chart_get_layout_root(d->target), v); }
int32_t _deepui_anim_callback_get_height(lv_anim_t * a) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); return d && d->target ? lv_obj_get_height(_deepui_chart_get_layout_root(d->target)) : 0; }
void _deepui_anim_callback_set_opacity(lv_anim_t * a, int32_t v) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); if(d && d->target) lv_obj_set_style_opa(_deepui_chart_get_layout_root(d->target), (lv_opa_t)v, LV_PART_MAIN | LV_STATE_DEFAULT); }
int32_t _deepui_anim_callback_get_opacity(lv_anim_t * a) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); return d && d->target ? lv_obj_get_style_opa(_deepui_chart_get_layout_root(d->target), LV_PART_MAIN) : 0; }
void _deepui_anim_callback_set_image_angle(lv_anim_t * a, int32_t v) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); if(d && d->target) lv_image_set_rotation(d->target, v); }
int32_t _deepui_anim_callback_get_image_angle(lv_anim_t * a) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); return d && d->target ? lv_image_get_rotation(d->target) : 0; }
void _deepui_anim_callback_set_image_zoom(lv_anim_t * a, int32_t v) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); if(d && d->target) lv_image_set_scale(d->target, v); }
int32_t _deepui_anim_callback_get_image_zoom(lv_anim_t * a) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); return d && d->target ? lv_image_get_scale(d->target) : 0; }
void _deepui_anim_callback_set_image_frame(lv_anim_t * a, int32_t v) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); if(d && d->target && d->imgset && d->imgset_size > 0) { if(v < 0) v = 0; if(v >= d->imgset_size) v = d->imgset_size - 1; d->val = v; lv_image_set_src(d->target, d->imgset[v]); } }
int32_t _deepui_anim_callback_get_image_frame(lv_anim_t * a) { deepui_anim_user_data_t * d = _deepui_anim_user_data(a); return d ? d->val : 0; }
/* 目标删除时立即停止关联动画，防止下一帧访问已释放的对象。 */
void _deepui_anim_target_deleted(lv_event_t * e)
{
    lv_anim_t * a = (lv_anim_t *)lv_event_get_user_data(e);
    lv_anim_custom_delete(a, NULL);
}

/* 动画结束或停止后释放对应上下文；此处不删除控件本身。 */
void _deepui_anim_callback_free_user_data(lv_anim_t * a)
{
    deepui_anim_user_data_t * d = _deepui_anim_user_data(a);
    if (d == NULL) return;
    /* 正常结束或手动停止时移除删除监听，避免保留已释放的动画指针。 */
    if (d->target != NULL) lv_obj_remove_event_cb_with_user_data(d->target, _deepui_anim_target_deleted, a);
    lv_free(d);
}
